export async function Page(props: PageProps) {
      const {
  account, rows, items, count, mode, enabled, fallback, selection, data,
  options, key, context, values, prototype, slots,
} = props;
      const ready = await preload();
      return <Shell ready={ready} preview={<p>Async preview {count}</p>}><main><Card children={(slots.header = <h2>Assigned header {rows.map(({ Choice = LocalChoice, ...row }) => <Choice children={<span>Locally bound {row.name}</span>} />)}</h2>, rows.map(({ Choice = LocalChoice, ...row }) => <Choice children={<span>Locally bound {row.name}</span>} />))}
      fallback={(slots.footer ??= <aside>Assigned footer {rows.map(({ Choice = LocalChoice, ...row }) => <Choice children={<span>Locally bound {row.name}</span>} />)}</aside>)}>
      {enabled && (slots.selected = <p>Selected {rows.map(({ Choice = LocalChoice, ...row }) => <Choice children={<span>Locally bound {row.name}</span>} />)}</p>)}
