type RowData = { id: string; name: string; [key: string]: unknown };

export const pages = {
      Page(props: PageProps, placeholder = <p>Parameter placeholder</p>) {
        const {
  account, rows, items, count, mode, enabled, fallback, selection, data,
  options, key, context, values, prototype, slots,
} = props;
        return <Shell fallback={placeholder}><main><Card children={(slots.header = <h2>Assigned header {(() => { const Choice = LocalChoice; return <Choice label={<b>Local label {count}</b>}>Inner {account.name}</Choice>; })()}</h2>, (() => { const Choice = LocalChoice; return <Choice label={<b>Local label {count}</b>}>Inner {account.name}</Choice>; })())}
      fallback={(slots.footer ??= <aside>Assigned footer {(() => { const Choice = LocalChoice; return <Choice label={<b>Local label {count}</b>}>Inner {account.name}</Choice>; })()}</aside>)}>
      {enabled && (slots.selected = <p>Selected {(() => { const Choice = LocalChoice; return <Choice label={<b>Local label {count}</b>}>Inner {account.name}</Choice>; })()}</p>)}
      Final visible children {count}
    </Card><footer>After assignment {account.name}</footer></main></Shell>;
      },
      get empty() { return <p>Independent getter page</p>; },
    };

